def norm(s):return re.sub(r'[〜～\s（）()：:・]','',re.sub(r'[（(][^）)]*[）)]','',s))
p=D/'lessons-n2.json';b=json.loads(p.read_text());base=b['grammar'][:195]
for e,fix in zip(b['grammar'][195:],extra):
 pattern,meaning,*rest=fix;e['pattern']=pattern
 match=next((x for x in base if norm(x['pattern'])==norm(pattern) or any(norm(z)==norm(pattern) for z in x['pattern'].split('・'))),None)
 if match:continue
 if len(rest)<3:continue
 e.update(meaning=meaning,explanation=rest[0],examples=[dict(ja=rest[1],bn=rest[2].replace('。','।'))]);base.append(e)
b['grammar']=base;p.write_text(json.dumps(b,ensure_ascii=False,separators=(',',':')))
