   ls=r.text(n,(80,w[1]+15,560,w[1]+75)).splitlines(); vals=[]
   for line in ls:
    if ':' in line:vals.append(re.sub(r'\s+','',line.split(':',1)[1]).replace('(','').replace(')',''))
   if len(vals)>=2:reads[int(w[4])]=vals[:2]
