for i,e in enumerate(b['kanji'],1):
 if i in reads:
  e['onyomi']=[x for x in reads[i][0].split('/') if x!='—'];e['kunyomi']=[x for x in reads[i][1].split('/') if x!='—']
p.write_text(json.dumps(b,ensure_ascii=False,separators=(',',':')))
